440	static void
441	tick_unk (ModeInfo *mi)
442	{
443	  unk_configuration *bp = &bps[MI_SCREEN(mi)];
444	  int wire = MI_IS_WIREFRAME(mi);
445	  double *points = generate_signal (mi);
446	  int linesp, frame;
447	
448	  /* Roll forward by one line (2 dlists per frame) */
449	  GLuint *cur = (GLuint *) malloc (bp->frames * 2 * sizeof(*cur));
450	  memcpy (cur, bp->lines, bp->frames * 2 * sizeof(*cur));
451	  memmove (bp->lines, bp->lines + 2 * bp->frames,
452	           sizeof(*bp->lines) * (bp->count-1) * bp->frames * 2);
453	  memcpy (bp->lines + (bp->count-1) * bp->frames * 2, cur,
454	          bp->frames * 2 * sizeof(*cur));
455	
456	  memmove (bp->heights, bp->heights + 1,
457	           sizeof(*bp->heights) * (bp->count-1));
458	  bp->heights[bp->count-1] = 0;
459	
460	  /* Regenerate the pair at the bottom. */
461	
462	  for (frame = 0; frame < bp->frames; frame++)
463	    {
464	      mi->polygon_count = 0;
465	      for (linesp = 0; linesp <= 1; linesp++)
466	        {
467	          int i;
468	
469	          glNewList (cur[frame * 2 + !linesp], GL_COMPILE);
470	          glBegin (linesp
471	                   ? GL_LINE_STRIP
472	                   : wire ? GL_LINES : GL_QUAD_STRIP);
473	          for (i = 0; i < bp->resolution; i++)
474	            {
475	              GLfloat x = i / (GLfloat) bp->resolution;
476	              GLfloat z = (points[i] + frand (0.05)) * bp->amplitude;
477	
478	              if (bp->mask)
479	                {
480	                  int h = bp->mask->height;  /* leave a 10% gutter */
481	                  int y = bp->frame_count % (int) (h * 1.1);
482	                  unsigned long p = (y < h ? XGetPixel (bp->mask, i, y) : 0);
483	                  unsigned long gray = ((p >> 8) & 0xFF);
484	                  z *= gray * bp->mask_scale / 255.0;
485	                }
486	
487	              if (z < 0) z = 0;
488	              if (z > bp->amplitude) z = bp->amplitude;
489	              glVertex3f (x, 0, z);
490	              if (! linesp)
491	                glVertex3f (x, 0, 0);
492	              mi->polygon_count++;
493	            }
494	          glEnd ();
495	          glEndList ();
496	        }
497	    }
498	
499	  bp->frame_count++;
500	  mi->polygon_count *= bp->count;
501	  mi->polygon_count += 5;  /* base */
502	
503	  free (cur);
504	  free (points);
505	}
