528	  if (bp->resolution < 1) bp->resolution = 1;
529	  if (bp->resolution > 300) bp->resolution = 300;
530	  if (bp->amplitude < 0.01) bp->amplitude = 0.01;
531	  if (bp->amplitude > 1) bp->amplitude = 1;
