547	  bp->base = glGenLists (1);
548	  glNewList (bp->base, GL_COMPILE);
549	  {
550	    GLfloat h1 = 0.01;
551	    GLfloat h2 = 0.02;
552	    GLfloat h3 = (h1 + h2) / 2;
553	    GLfloat s = 0.505;
554	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
555	    glVertex3f (-s, -s, -h1);
556	    glVertex3f ( s, -s, -h1);
557	    glVertex3f ( s,  s, -h1);
558	    glVertex3f (-s,  s, -h1);
559	    glEnd();
560	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
561	    glVertex3f (-s, -s, 0);
562	    glVertex3f (-s, -s, -h2);
563	    glVertex3f ( s, -s, -h2);
564	    glVertex3f ( s, -s, 0);
565	    glEnd();
566	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
567	    glVertex3f (-s, -s, 0);
568	    glVertex3f (-s, -s, -h2);
569	    glVertex3f (-s,  s, -h2);
570	    glVertex3f (-s,  s, 0);
571	    glEnd();
572	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
573	    glVertex3f ( s, -s, 0);
574	    glVertex3f ( s, -s, -h2);
575	    glVertex3f ( s,  s, -h2);
576	    glVertex3f ( s,  s, 0);
577	    glEnd();
578	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
579	    glVertex3f (-s,  s, 0);
580	    glVertex3f (-s,  s, -h2);
581	    glVertex3f ( s,  s, -h2);
582	    glVertex3f ( s,  s, 0);
583	    glEnd();
584	
585	    glColor3fv (bp->fg);
586	    glBegin (GL_LINE_LOOP);
587	    s -= 0.01;
588	    glVertex3f (-s, -s, -h3);
589	    glVertex3f ( s, -s, -h3);
590	    glVertex3f ( s,  s, -h3);
591	    glVertex3f (-s,  s, -h3);
592	    glEnd();
593	  }
594	  glEndList ();
595	
596	  if (! wire)
597	    {
598	      glEnable (GL_LINE_SMOOTH);
599	      glHint (GL_LINE_SMOOTH_HINT, GL_NICEST);
600	      glBlendFunc (GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA); 
601	      glEnable (GL_BLEND);
602	    }
603	
604	  glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
605	
606	  for (i = 0; i < bp->count; i++)
607	    tick_unk (mi);
