611	ENTRYPOINT void
612	draw_unk (ModeInfo *mi)
613	{
614	  unk_configuration *bp = &bps[MI_SCREEN(mi)];
615	  int wire = MI_IS_WIREFRAME(mi);
616	  Display *dpy = MI_DISPLAY(mi);
617	  Window window = MI_WINDOW(mi);
618	  GLfloat step = 1.0 / bp->count;
619	  double speed = (0.6 / bp->speed) * (80.0 / bp->count);
620	  double now = double_time();
621	  double ratio = (now - bp->tick) / speed;
622	  int frame;
623	  int i;
624	
625	  ratio = (ratio < 0 ? 0 : ratio > 1 ? 1 : ratio);
626	
627	  if (!bp->glx_context)
628	    return;
629	
630	  glXMakeCurrent(MI_DISPLAY(mi), MI_WINDOW(mi), *bp->glx_context);
631	
632	  glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
633	
634	  glShadeModel (GL_FLAT);
635	  glEnable (GL_DEPTH_TEST);
636	  glDisable (GL_CULL_FACE);
637	
638	  glPushMatrix ();
639	
640	  glRotatef(current_device_rotation(), 0, 0, 1);
641	
642	  gltrackball_rotate (bp->trackball);
643	
644	  glRotatef (-45, 1, 0, 0);
645	
646	  i = bp->orthop ? 15 : 17;
647	  glScalef (i / bp->aspect, i, i / bp->aspect);
648	
649	  glDisable (GL_POLYGON_OFFSET_FILL);
650	  if (wire)
651	    glColor3f (0.5 * bp->fg[0], 0.5 * bp->fg[1], 0.5 * bp->fg[2]);
652	  else
653	    glColor4fv (bp->bg);
654	  glCallList (bp->base);
655	
656	  /* So the masking quads don't interfere with the lines.
657	     These numbers are empirical black magic. */
658	  glEnable (GL_POLYGON_OFFSET_FILL);
659	
660	# ifdef DEBUG
661	  glPolygonOffset (poly1, poly2);
662	# else
663	  glPolygonOffset (0.5, 0.5);
664	# endif
665	
666	  glTranslatef (-0.5, 0.55 + step*ratio, 0);
667	
668	  frame = random() % bp->frames;
669	  for (i = 0; i < bp->count; i++)
670	    {
671	      int j = i * bp->frames * 2 + frame * 2;
672	      GLfloat s  = ease (EASE_IN_OUT_SINE, bp->heights[i]);
673	      GLfloat s2 = ease (EASE_IN_OUT_SINE, bp->heights[i] * 1.5);
674	
675	      glPushMatrix();
676	      glScalef (1, 1, s);
677	      glColor4f (bp->fg[0], bp->fg[1], bp->fg[2], s2);
678	      glCallList (bp->lines[j]);	/* curve */
679	      s = 1;
680	      if (wire)
681	        glColor4f (0.5 * bp->fg[0], 0.5 * bp->fg[1], 0.5 * bp->fg[2], s);
682	      else
683	        glColor4f (bp->bg[0], bp->bg[1], bp->bg[2], s);
684	      glCallList (bp->lines[j+1]);	/* shield */
685	      glPopMatrix();
686	      glTranslatef (0, -step, 0);
687	    }
688	
689	  glPopMatrix ();
690	
691	  if (mi->fps_p) do_fps (mi);
692	  glFinish();
693	
694	  if (!bp->button_down_p)
695	    {
696	      /* Set height/fade based on distance from either edge. */
697	      GLfloat dist = bp->count * 0.05;
698	      int i;
699	      for (i = 0; i < bp->count; i++)
700	        {
701	          GLfloat i2 = i - ratio;
702	          GLfloat h = ((i2 < bp->count/2 ? i2 : (bp->count - 1 - i2))
703	                       / dist);
704	          bp->heights[i] = (h > 1 ? 1 : h < 0 ? 0 : h);
705	        }
706	
707	      if (bp->tick + speed <= now)     /* Add a new row. */
708	        {
709	          tick_unk (mi);
710	          bp->tick = now;
711	        }
712	    }
713	
714	  glXSwapBuffers(dpy, window);
715	}
